@namespace sv_ad77d89b280f4a79a4821de2fe1ecdf8.Components.Pages.Apply
@using sv_ad77d89b280f4a79a4821de2fe1ecdf8.Models

<h3>Personal Information</h3>

<EditForm Model="Model" OnValidSubmit="HandleNext" FormName="personal-info">
    <div class="form-group">
        <label>Full Name <span class="required">*</span></label>
        <InputText @bind-Value="Model.FullName" class="form-control" />
    </div>

    <div class="form-group">
        <label>Email <span class="required">*</span></label>
        <InputText @bind-Value="Model.Email" class="form-control" type="email" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <span class="field-error">@_emailError</span>
        }
    </div>

    <div class="form-group">
        <label>Phone <span class="required">*</span></label>
        <InputText @bind-Value="Model.Phone" class="form-control" type="tel" />
    </div>

    <div class="form-group">
        <label>Address <span class="required">*</span></label>
        <InputTextArea @bind-Value="Model.Address" class="form-control" rows="2" />
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="alert alert-danger">@_validationError</div>
    }

    <div class="step-buttons">
        <span></span>
        <button type="submit" class="btn btn-primary" disabled="@_isValidating">
            @(_isValidating ? "Validating…" : "Next →")
        </button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback<string?> OnEmailValidation { get; set; }

    private string? _validationError;
    private string? _emailError;
    private bool _isValidating;

    private async Task HandleNext()
    {
        _validationError = null;
        _emailError = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            _validationError = "All fields are required.";
            return;
        }

        _isValidating = true;
        try
        {
            await OnEmailValidation.InvokeAsync(Model.Email);
        }
        finally
        {
            _isValidating = false;
        }
    }

    public void ShowEmailError(string error)
    {
        _emailError = error;
        StateHasChanged();
    }

    public void ClearEmailError()
    {
        _emailError = null;
    }
}

@namespace sv_ad77d89b280f4a79a4821de2fe1ecdf8.Components.Pages.Apply
@using sv_ad77d89b280f4a79a4821de2fe1ecdf8.Models

<h3>Work History</h3>

<EditForm Model="_dummy" OnValidSubmit="HandleNext" FormName="work-history">
    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]"
                       Index="index + 1"
                       CanRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button type="button" class="btn btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="alert alert-danger">@_validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">← Back</button>
        <button type="submit" class="btn btn-primary">Next →</button>
    </div>
</EditForm>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private readonly object _dummy = new();
    private string? _validationError;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        _validationError = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) ||
                string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate is null)
            {
                _validationError = "Each position requires at least a company name, job title, and start date.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

