@namespace sv_ad77d89b280f4a79a4821de2fe1ecdf8.Components.Pages.Apply
@using sv_ad77d89b280f4a79a4821de2fe1ecdf8.Models

<h3>Review &amp; Submit</h3>

<section class="review-section">
    <div class="review-header">
        <h4>Personal Information</h4>
        <button type="button" class="btn-link" @onclick='() => OnEditStep.InvokeAsync(0)'>Edit</button>
    </div>
    <dl>
        <dt>Name</dt><dd>@Personal.FullName</dd>
        <dt>Email</dt><dd>@Personal.Email</dd>
        <dt>Phone</dt><dd>@Personal.Phone</dd>
        <dt>Address</dt><dd>@Personal.Address</dd>
    </dl>
</section>

<section class="review-section">
    <div class="review-header">
        <h4>Work History</h4>
        <button type="button" class="btn-link" @onclick='() => OnEditStep.InvokeAsync(1)'>Edit</button>
    </div>
    @foreach (var entry in WorkEntries)
    {
        <div class="review-work-entry">
            <strong>@entry.Title</strong> at <strong>@entry.Company</strong>
            <div class="review-dates">
                @entry.StartDate?.ToString("MMM yyyy")
                – @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
            </div>
            @if (!string.IsNullOrWhiteSpace(entry.Description))
            {
                <p>@entry.Description</p>
            }
        </div>
    }
</section>

<section class="review-section">
    <div class="review-header">
        <h4>References</h4>
        <button type="button" class="btn-link" @onclick='() => OnEditStep.InvokeAsync(2)'>Edit</button>
    </div>
    @foreach (var r in References)
    {
        <div class="review-reference">
            <strong>@r.Name</strong> (@r.Relationship)
            <br />@r.Email · @r.Phone
        </div>
    }
</section>

<section class="review-section">
    <div class="review-header">
        <h4>Cover Letter</h4>
        <button type="button" class="btn-link" @onclick='() => OnEditStep.InvokeAsync(3)'>Edit</button>
    </div>
    <p class="cover-letter-preview">@CoverLetter</p>
</section>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="step-buttons">
    <button type="button" class="btn btn-outline" @onclick="OnBack">← Back</button>
    <button type="button" class="btn btn-primary btn-submit" @onclick="OnSubmit" disabled="@IsSubmitting">
        @(IsSubmitting ? "Submitting…" : "Submit Application")
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
}

.review-section {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    padding: 1rem 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.5rem;
}

.review-header h4 {
    margin: 0;
    font-size: 1rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    font-size: 0.9rem;
    padding: 0;
}

.btn-link:hover {
    text-decoration: underline;
}

dl {
    display: grid;
    grid-template-columns: auto 1fr;
    gap: 0.25rem 1rem;
    margin: 0;
}

dt {
    font-weight: 600;
    color: #495057;
}

dd {
    margin: 0;
}

.review-work-entry,
.review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.review-dates {
    font-size: 0.85rem;
    color: #6c757d;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 0.75rem;
    border-radius: 0.25rem;
    margin: 0;
}

