+        <label>Full Name <span class="required">*</span></label>
+        <InputText @bind-Value="Model.FullName" class="form-control" />
+    </div>
+
+    <div class="form-group">
+        <label>Email <span class="required">*</span></label>
+        <InputText @bind-Value="Model.Email" class="form-control" type="email" />
+        @if (!string.IsNullOrEmpty(_emailError))
+        {
+            <span class="field-error">@_emailError</span>
+        }
+    </div>
+
+    <div class="form-group">
+        <label>Phone <span class="required">*</span></label>
+        <InputText @bind-Value="Model.Phone" class="form-control" type="tel" />
+    </div>
+
+    <div class="form-group">
+        <label>Address <span class="required">*</span></label>
+        <InputTextArea @bind-Value="Model.Address" class="form-control" rows="2" />
+    </div>
+
+    @if (!string.IsNullOrEmpty(_validationError))
+    {
+        <div class="alert alert-danger">@_validationError</div>
+    }
+
+    <div class="step-buttons">
+        <span></span>
+        <button type="submit" class="btn btn-primary" disabled="@_isValidating">
+            @(_isValidating ? "Validating…" : "Next →")
+        </button>
+    </div>
+</EditForm>
+
+@code {
+    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
+    [Parameter] public EventCallback OnNext { get; set; }
+    [Parameter] public EventCallback<string?> OnEmailValidation { get; set; }
+
+    private string? _validationError;
+    private string? _emailError;
+    private bool _isValidating;
+
+    private async Task HandleNext()
+    {
+        _validationError = null;
+        _emailError = null;
+
+        if (string.IsNullOrWhiteSpace(Model.FullName) ||
+            string.IsNullOrWhiteSpace(Model.Email) ||
+            string.IsNullOrWhiteSpace(Model.Phone) ||
+            string.IsNullOrWhiteSpace(Model.Address))
+        {
+            _validationError = "All fields are required.";
+            return;
+        }
+
+        _isValidating = true;
+        try
+        {
+            await OnEmailValidation.InvokeAsync(Model.Email);
+        }
+        finally
+        {
+            _isValidating = false;
+        }
+    }
+
+    public void ShowEmailError(string error)
+    {
+        _emailError = error;
+        StateHasChanged();
+    }
+
+    public void ClearEmailError()
+    {
+        _emailError = null;
+    }
+}
+

