    {
        <div class="alert alert-danger">@_validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn btn-outline" @onclick="OnBack">← Back</button>
        <button type="submit" class="btn btn-primary">Next →</button>
    </div>
