arguments.file_text:
@page "/apply"
@rendermode InteractiveServer

@namespace sv_ad77d89b280f4a79a4821de2fe1ecdf8.Components.Pages.Apply
@using sv_ad77d89b280f4a79a4821de2fe1ecdf8.Models
@using sv_ad77d89b280f4a79a4821de2fe1ecdf8.Services

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2>Job Application</h2>

    @if (_submittedId is not null)
    {
        <div class="confirmation">
            <div class="confirmation-icon">✓</div>
            <h3>Application Submitted!</h3>
            <p>Your application has been received. Your confirmation number is:</p>
            <div class="confirmation-id">@_submittedId</div>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep" OnStepClicked="GoToStep" />

        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep @ref="_personalInfoStep"
                                  Model="_personal"
                                  OnNext="HandlePersonalNext"
                                  OnEmailValidation="ValidateEmail" />
                break;

            case 1:
                <WorkHistoryStep Entries="_workEntries"
                                 OnNext="() => GoToStep(2)"
                                 OnBack="() => GoToStep(0)" />
                break;

            case 2:
                <ReferencesStep References="_references"
                                OnNext="() => GoToStep(3)"
                                OnBack="() => GoToStep(1)" />
                break;

            case 3:
                <CoverLetterStep @bind-CoverLetter="_coverLetter"
                                 OnNext="() => GoToStep(4)"
                                 OnBack="() => GoToStep(2)" />
                break;

            case 4:
                <ReviewStep Personal="_personal"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="@_coverLetter"
                            IsSubmitting="_isSubmitting"
                            ErrorMessage="@_submitError"
                            OnBack="() => GoToStep(3)"
                            OnSubmit="SubmitApplication"
                            OnEditStep="GoToStep" />
                break;
        }
    }
</div>

@code {
    private int _currentStep;
    private PersonalInfoStep? _personalInfoStep;

    // Form state
    private readonly PersonalInfoModel _personal = new();
    private readonly List<WorkEntryModel> _workEntries = [new()];
    private readonly List<ReferenceModel> _references = [new(), new()];
    private string _coverLetter = "";

    // Submission state
    private bool _isSubmitting;
    private string? _submitError;
    private int? _submittedId;

    private void GoToStep(int step)
    {
        if (step >= 0 && step <= 4)
            _currentStep = step;
    }

    private async Task HandlePersonalNext()
    {
        // This is called after PersonalInfoStep validates required fields.
        // Email validation is handled via the OnEmailValidation callback.
        await Task.CompletedTask;
    }

    private async Task ValidateEmail(string? email)
    {
        if (string.IsNullOrWhiteSpace(email))
            return;

        var isValid = await ApplicationService.ValidateEmailAsync(email);
        if (!isValid)
        {
            _personalInfoStep?.ShowEmailError("Please enter a valid email address.");
        }
        else
        {
            _personalInfoStep?.ClearEmailError();
            GoToStep(1);
        }
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _submitError = null;

        try
        {
            var application = new JobApplication(
                _personal.ToRecord(),
                new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
                _references.Select(r => r.ToRecord()).ToList(),
                _coverLetter
            );

            _submittedId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

.apply-container {
    max-width: 720px;
    margin: 2rem auto;
    padding: 0 1rem;
}

.apply-container h2 {
    margin-bottom: 1.5rem;
}

/* Shared form styles */
:deep(.form-group) {
    margin-bottom: 1rem;
}

:deep(.form-group label) {
    display: block;
    font-weight: 500;
    margin-bottom: 0.25rem;
    font-size: 0.9rem;
}

:deep(.form-control) {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    line-height: 1.5;
    box-sizing: border-box;
    transition: border-color 0.15s;
}

:deep(.form-control:focus) {
    outline: none;
    border-color: #86b7fe;
    box-shadow: 0 0 0 0.2rem rgba(13, 110, 253, 0.25);
}

:deep(.form-row) {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

:deep(.required) {
    color: #dc3545;
}

:deep(.field-error) {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

:deep(.checkbox-label) {
    display: inline-flex !important;
    align-items: center;
    gap: 0.35rem;
    font-weight: 400 !important;
    margin-top: 0.35rem;
    font-size: 0.85rem;
}

:deep(.alert) {
    padding: 0.75rem 1rem;
    border-radius: 0.375rem;
    margin: 1rem 0;
}

:deep(.alert-danger) {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
}

/* Buttons */
:deep(.btn) {
    padding: 0.5rem 1.25rem;
    border-radius: 0.375rem;
    font-size: 0.95rem;
    cursor: pointer;
    border: 1px solid transparent;
    transition: background 0.15s, opacity 0.15s;
}

:deep(.btn:disabled) {
    opacity: 0.65;
    cursor: not-allowed;
}

:deep(.btn-primary) {
    background: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

:deep(.btn-primary:hover:not(:disabled)) {
    background: #0b5ed7;
}

:deep(.btn-secondary) {
    background: #f8f9fa;
    color: #212529;
    border-color: #dee2e6;
}

:deep(.btn-secondary:hover) {
    background: #e9ecef;
}

:deep(.btn-outline) {
    background: transparent;
    color: #6c757d;
    border-color: #6c757d;
}

:deep(.btn-outline:hover) {
    background: #6c757d;
    color: #fff;
}

:deep(.btn-danger-outline) {
    background: transparent;
    color: #dc3545;
    border-color: #dc3545;
    font-size: 0.85rem;
    padding: 0.3rem 0.75rem;
}

:deep(.btn-danger-outline:hover) {
    background: #dc3545;
    color: #fff;
}

:deep(.btn-submit) {
    padding: 0.6rem 2rem;
    font-weight: 600;
}

:deep(.step-buttons) {
    display: flex;
    justify-content: space-between;
    margin-top: 1.5rem;
    padding-top: 1rem;
    border-top: 1px solid #dee2e6;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.confirmation-icon {
    width: 4rem;
    height: 4rem;
    border-radius: 50%;
    background: #198754;
    color: #fff;
    font-size: 2rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 1rem;
}

.confirmation h3 {
    color: #198754;
    margin-bottom: 0.5rem;
}

.confirmation-id {
    font-size: 1.5rem;
    font-weight: 700;
    color: #0d6efd;
    margin-top: 0.5rem;
}

