toolArgs.file_text:
@page "/apply"
@rendermode InteractiveServer

@namespace sv_ad77d89b280f4a79a4821de2fe1ecdf8.Components.Pages.Apply
@using sv_ad77d89b280f4a79a4821de2fe1ecdf8.Models
@using sv_ad77d89b280f4a79a4821de2fe1ecdf8.Services

@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-container">
    <h2>Job Application</h2>

    @if (_submittedId is not null)
    {
        <div class="confirmation">
            <div class="confirmation-icon">✓</div>
            <h3>Application Submitted!</h3>
            <p>Your application has been received. Your confirmation number is:</p>
            <div class="confirmation-id">@_submittedId</div>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep" OnStepClicked="GoToStep" />

        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep @ref="_personalInfoStep"
                                  Model="_personal"
                                  OnNext="HandlePersonalNext"
                                  OnEmailValidation="ValidateEmail" />
                break;

            case 1:
                <WorkHistoryStep Entries="_workEntries"
                                 OnNext="() => GoToStep(2)"
                                 OnBack="() => GoToStep(0)" />
                break;

            case 2:
                <ReferencesStep References="_references"
                                OnNext="() => GoToStep(3)"
                                OnBack="() => GoToStep(1)" />
                break;

            case 3:
                <CoverLetterStep @bind-CoverLetter="_coverLetter"
                                 OnNext="() => GoToStep(4)"
                                 OnBack="() => GoToStep(2)" />
                break;

            case 4:
                <ReviewStep Personal="_personal"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="@_coverLetter"
                            IsSubmitting="_isSubmitting"
                            ErrorMessage="@_submitError"
                            OnBack="() => GoToStep(3)"
                            OnSubmit="SubmitApplication"
                            OnEditStep="GoToStep" />
                break;
        }
    }
</div>

@code {
    private int _currentStep;
    private PersonalInfoStep? _personalInfoStep;

    // Form state
    private readonly PersonalInfoModel _personal = new();
    private readonly List<WorkEntryModel> _workEntries = [new()];
    private readonly List<ReferenceModel> _references = [new(), new()];
    private string _coverLetter = "";

    // Submission state
    private bool _isSubmitting;
    private string? _submitError;
    private int? _submittedId;

    private void GoToStep(int step)
    {
        if (step >= 0 && step <= 4)
            _currentStep = step;
    }

    private async Task HandlePersonalNext()
    {
        // This is called after PersonalInfoStep validates required fields.
        // Email validation is handled via the OnEmailValidation callback.
        await Task.CompletedTask;
    }

    private async Task ValidateEmail(string? email)
    {
        if (string.IsNullOrWhiteSpace(email))
            return;

        var isValid = await ApplicationService.ValidateEmailAsync(email);
        if (!isValid)
        {
            _personalInfoStep?.ShowEmailError("Please enter a valid email address.");
        }
        else
        {
            _personalInfoStep?.ClearEmailError();
            GoToStep(1);
        }
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _submitError = null;

        try
        {
            var application = new JobApplication(
                _personal.ToRecord(),
                new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
                _references.Select(r => r.ToRecord()).ToList(),
                _coverLetter
            );

            _submittedId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

